  "content": "1|import { createStableStateFromTemplateSeeds } from '../../../../domain/component-designer/templateStateBuilder';
2|import { getDesignerDraft } from '../../../../server/domain/component-designer/drafts';
3|import { sanitizeDraftId } from '../../../../server/domain/component-designer/draftIo';
4|import {
5|  getBuiltInComponentRecord,
6|  getBuiltInPresetId,
7|  isBuiltInComponentId,
8|  toBuiltInComponentId,
9|} from '../../../../domain/component-designer/layout-presets/builtInComponents';
10|import type { NewLayoutPresetId } from '../../../../domain/component-designer/layout-presets/types';
11|import type { DesignerDocument } from '../../../../domain/component-designer/types';
12|import type { NativeToolDefinition } from '../ToolRegistry';
13|import { createDraftId, putAgentDraft } from './agentDraftStore';
14|
15|export const DRAFT_COMPONENT_LAYOUT_TOOL_NAME = 'draft_component_layout';
16|
17|const isRecord = (value: unknown): value is Record<string, unknown> => (
18|  Boolean(value) && typeof value === 'object' && !Array.isArray(value)
19|);
20|
21|const slugifyName = (name: string): string => (
22|  name.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'untitled-component'
23|);
24|
25|export const executeDraftComponentLayout = async (args: Record<string, unknown>) => {
26|  const name = typeof args.name === 'string' ? args.name.trim() : '';
27|  if (!name) {
28|    return { ok: false as const, summary: 'Component name is required.', error: 'missing_name' };
29|  }
30|
31|  const folder = typeof args.folder === 'string' && args.folder.trim()
32|    ? args.folder.trim().toLowerCase()
33|    : 'general';
34|  const description = typeof args.description === 'string' ? args.description.trim() : undefined;
35|  const templateId = typeof args.templateId === 'string' ? args.templateId.trim() : '';
36|  const layoutIdArg = typeof args.layoutId === 'string' ? args.layoutId.trim() : '';
37|  const componentId = slugifyName(name);
38|  const layoutId = sanitizeDraftId(componentId);
39|
40|  let document: DesignerDocument;
41|  let bindingDefinitions: Record<string, unknown> = {};
42|  let baseLayoutId: string | undefined;
43|
44|  if (isRecord(args.document)) {
45|    document = args.document as DesignerDocument;
46|  } else if (layoutIdArg) {
47|    baseLayoutId = layoutIdArg;
48|    const existing = isBuiltInComponentId(layoutIdArg)
49|      ? getBuiltInComponentRecord(layoutIdArg)
50|      : getDesignerDraft(layoutIdArg);
51|    if (!existing) {
52|      return { ok: false as const, summary: `Layout "${layoutIdArg}" was not found.`, error: 'layout_not_found' };
53|    }
54|    document = structuredClone(existing.document);
55|    bindingDefinitions = structuredClone(existing.bindingDefinitions ?? {});
56|  } else if (templateId) {
57|    const builtInId = isBuiltInComponentId(templateId)
58|      ? templateId
59|      : toBuiltInComponentId(templateId as NewLayoutPresetId);
60|    const fromPreset = getBuiltInPresetId(builtInId)
61|      ? getBuiltInComponentRecord(builtInId)
62|      : null;
63|    if (!fromPreset) {
64|      return {
65|        ok: false as const,
66|        summary: `Built-in template "${templateId}" was not found.`,
67|        error: 'template_not_found',
68|      };
69|    }
70|    document = structuredClone(fromPreset.document);
71|    bindingDefinitions = structuredClone(fromPreset.bindingDefinitions ?? {});
72|  } else {
73|    const built = createStableStateFromTemplateSeeds([], layoutId, name);
74|    document = built.state.document;
75|    bindingDefinitions = built.state.bindingDefinitions ?? {};
76|  }
77|
78|  document = {
79|    ...document,
80|    id: layoutId,
81|    name,
82|  };
83|
84|  const draftId = createDraftId();
85|  const draft = putAgentDraft({
86|    kind: 'component_layout',
87|    id: draftId,
88|    layoutId,
89|    name,
90|    folder,
91|    description,
92|    document,
93|    bindingDefinitions: bindingDefinitions as Record<string, import('../../../../domain/component-designer/types').DesignerBindingDefinition>,
94|    baseLayoutId,
95|  }) as import('./agentDraftStore').ComponentLayoutDraft;
96|
97|  return {
98|    ok: true as const,
99|    summary: `Drafted component layout "${name}" (${draft.layoutId}).`,
100|    data: {
101|      draftId: draft.id,
102|      layoutId: draft.layoutId,
103|      name: draft.name,
104|      folder: draft.folder,
105|      nodeCount: Object.keys(draft.document.nodes).length,
106|      templateId: templateId || undefined,
107|    },
108|    artifacts: [{ kind: 'draft' as const, id: draft.id, label: draft.name }],
109|  };
110|};
111|
112|export const draftComponentLayoutTool: NativeToolDefinition = {
113|  name: DRAFT_COMPONENT_LAYOUT_TOOL_NAME,
114|  description: 'Drafts a Component Designer layout (no save to disk). Use when building a single screen or UI from built-in layout presets (contact-form, kpi-metrics-grid, …) — for a multi-page app (shell + pages + menu), use draft_application_scaffold instead. Every generated form control must include label plus a plain-language hint so the studio page guide can explain it (auto-form/CRUD builders already emit hint). After insert, set hint via designer_set_prop when adding fields by hand. Returns draftId, folder, nodeCount, templateId, and a draft artifact.',
115|  group: 'draft',
116|  parameters: {
117|    type: 'object',
118|    properties: {
119|      name: { type: 'string', description: 'Component display name' },
120|      folder: { type: 'string', description: 'Component folder (default: general)' },
121|      templateId: { type: 'string', description: 'Built-in layout preset id (contact-form, auth-login, kpi-metrics-grid, …) or builtin-<presetId>' },
122|      layoutId: { type: 'string', description: 'Existing layout/draft id to base changes on' },
123|      description: { type: 'string', description: 'Optional draft description' },
124|      document: { type: 'object', description: 'Full DesignerDocument replacement when editing the open Live Designer canvas from a snapshot' },
125|      bindingDefinitions: { type: 'object', description: 'Optional binding definitions to store with the document' },
126|    },
127|    required: ['name'],
128|  },
129|  execute: executeDraftComponentLayout,
130|};
131|"
}
